import{_ as t,o as a,c as o,aF as d}from"./chunks/framework.CNkxH4QO.js";const b=JSON.parse('{"title":"krawler-icos","description":"A Krawler based service to download atmospheric data from the ICOS Data Portal.","frontmatter":{"title":"krawler-icos","description":"A Krawler based service to download atmospheric data from the ICOS Data Portal."},"headers":[],"relativePath":"packages/krawler-icos/index.md","filePath":"packages/krawler-icos/index.md"}'),r={name:"packages/krawler-icos/index.md"};function i(s,e,c,n,l,h){return a(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="krawler-icos" tabindex="-1">krawler-icos <a class="header-anchor" href="#krawler-icos" aria-label="Permalink to &quot;krawler-icos&quot;">​</a></h1><p><em>A Krawler based service to download atmospheric data from the <a href="https://data.icos-cp.eu/portal/" target="_blank" rel="noreferrer">ICOS Data Portal</a>.</em></p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The <strong>krawler-icos</strong> job scrapes atmospheric data from the <a href="https://www.icos-cp.eu/" target="_blank" rel="noreferrer">ICOS API</a>. The downloaded data are stored within a <a href="https://www.mongodb.com/" target="_blank" rel="noreferrer">MongoDB</a> database in 2 collections:</p><ul><li>the <code>icos-observations</code> collection stores the observation data</li><li>the <code>icos-stations</code> collection stores the station positions</li></ul><p>All records are stored in <a href="https://fr.wikipedia.org/wiki/GeoJSON" target="_blank" rel="noreferrer">GeoJson</a> format.</p><p>The project consists in 2 jobs:</p><ul><li>the <code>stations</code> job scrapes the available stations according a specific cron expression. By default, every day at midnight.</li><li>the <code>observations</code> job scrapes the observations data according a specific cron expression. By default every hour.</li></ul><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><h3 id="stations" tabindex="-1">Stations <a class="header-anchor" href="#stations" aria-label="Permalink to &quot;Stations&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th></tr></thead><tbody><tr><td><code>DB_URL</code></td><td>The database URL. The default value is <code>mongodb://127.0.0.1:27017/icos</code></td></tr><tr><td><code>OBJECT_SPEC_FILTER</code></td><td>A filter used to select only latest data objects containing this pattern. The default value is <code>radon data</code>, could be eg <code>CO data</code>, <code>CO2 data</code>, <code>CH4 data</code></td></tr><tr><td><code>HISTORY</code></td><td>The duration of the observations data history the job has to download. It must be expressed in seconds and the default value is <code>86 400 000</code> (1 day)</td></tr><tr><td><code>DEBUG</code></td><td>Enables debug output. Set it to <code>krawler*</code> to enable full output. By default it is undefined.</td></tr></tbody></table><h3 id="observations" tabindex="-1">Observations <a class="header-anchor" href="#observations" aria-label="Permalink to &quot;Observations&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th></tr></thead><tbody><tr><td><code>DB_URL</code></td><td>The database URL. The default value is <code>mongodb://127.0.0.1:27017/icos</code></td></tr><tr><td><code>TTL</code></td><td>The observations data time to live. It must be expressed in seconds and the default value is <code>604 800</code> (7 days)</td></tr><tr><td><code>OBJECT_SPEC_FILTER</code></td><td>A filter used to select only latest data objects containing this pattern. The default value is <code>radon data</code>, could be eg <code>CO data</code>, <code>CO2 data</code>, <code>CH4 data</code></td></tr><tr><td><code>OBJECT_VARIABLE</code></td><td>The name of the variable contained in the corresponding data objects. The default value is <code>rn</code>, could be eg <code>co</code>, <code>co2</code>, <code>ch4</code></td></tr><tr><td><code>HISTORY</code></td><td>The duration of the observations data history the job has to download. It must be expressed in seconds and the default value is <code>86 400 000</code> (1 day)</td></tr><tr><td><code>DEBUG</code></td><td>Enables debug output. Set it to <code>krawler*</code> to enable full output. By default it is undefined.</td></tr></tbody></table><h2 id="deployment" tabindex="-1">Deployment <a class="header-anchor" href="#deployment" aria-label="Permalink to &quot;Deployment&quot;">​</a></h2><p>We personally use <a href="https://kalisio.github.io/kargo/" target="_blank" rel="noreferrer">Kargo</a> to deploy the service.</p>',15)])])}const p=t(r,[["render",i]]);export{b as __pageData,p as default};
